def education_profile(commune_name: str):
    """Retourne les données scolaires réelles d'une commune (ou None)."""
    return EDUCATION_ALGER.get(commune_name)


def education_totals():
    """Totaux Alger (élèves, établissements)."""
    e = EDUCATION_ALGER.values()
    return {
        "communes": len(EDUCATION_ALGER),
        "eleves_total": sum(x["eleves_secondaire"] + x["eleves_moyen"] for x in e),
        "lycees": sum(x["lycees"] for x in e),
        "cems": sum(x["cems"] for x in e),
        "enseignants": sum(x["enseignants_sec"] + x["enseignants_moyen"] for x in e),
    }